func (st DBstore) ListByDatasource(ctx context.Context, dsUID string) ([]ngmodels.AlertRule, error) {
	if dsUID == "" {
		return nil, fmt.Errorf("datasource UID cannot be empty")
	}
	rules, err := st.ListAlertRules(ctx, &ngmodels.ListAlertRulesQuery{
		DataSourceUIDs: []string{dsUID},
	})
	if err != nil {
		return nil, err
	}
	result := make([]ngmodels.AlertRule, 0, len(rules))
	for _, r := range rules {
		if r != nil {
			result = append(result, *r)
		}
	}
	return result, nil
}
